import sqlite3
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
q=lambda s:con.execute(s).fetchall()
print('user_version',q('pragma user_version'))
print('mq x vs',q("select metadata_quality,verification_status,count(*) from evidence_sources group by 1,2"))
bad="(metadata_quality='AUTHOR-TITLE-ONLY' or verification_status is null)"
print('bad rows',q(f"select count(*) from evidence_sources where {bad}"))
tabs=[t for (t,) in q("select name from sqlite_master where type='table'")]
for t in tabs:
    cols=[c[1] for c in con.execute(f'pragma table_info("{t}")')]
    n=q(f'select count(*) from "{t}"')[0][0]
    for col in cols:
        if 'ref_id' in col and t!='evidence_sources':
            try:
                k=q(f'select count(distinct "{col}") from "{t}" where "{col}" in (select ref_id from evidence_sources where {bad})')[0][0]
            except Exception as e: k=str(e)
            if k: print('  bad source referenced by',t,col,k,'(table rows',n,')')
for t in ('best_practice_synthesis','specifications','judgment_handoff','gap_mining','term_aliases'):
    if t in tabs: print(t,q(f'select count(*) from "{t}"'))
